@import url('');

:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  --ink: #f5f0df;
  --muted: #a8ad9d;
  --bg: #182a2a;
  --card: #243b38;
  --panel: #1d302e;
  --mint: #a8d8a0;
  --amber: #f4c96b;
  --line: #45605a;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  color: var(--ink);
  background-color: var(--bg);
  background-image: radial-gradient(#35514b 1px, transparent 1px);
  background-size: 18px 18px;
}
button, select { font: inherit; }
.thermostat {
  width: min(100%, 420px);
  padding: 28px;
  border: 2px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  box-shadow: 0 12px 0 #10201f, 0 24px 50px #0c1919aa;
}
.header { display: flex; align-items: center; gap: 14px; padding-bottom: 22px; border-bottom: 1px solid var(--line); }
.pixel-mark { width: 44px; height: 44px; display: grid; place-items: center; color: var(--bg); background: var(--mint); border-radius: 8px; font-size: 28px; }
.eyebrow, .label { margin: 0; color: var(--muted); font-size: 0.8rem; font-weight: 750; letter-spacing: 0.12em; }
h1 { margin: 4px 0 0; font-size: 1.35rem; line-height: 1.2; }
.temperature-panel { padding: 28px 0 24px; text-align: center; }
.temperature { margin: 8px 0 2px; color: var(--mint); font-size: clamp(4.25rem, 20vw, 6rem); font-weight: 750; letter-spacing: -0.07em; line-height: 1.05; font-variant-numeric: tabular-nums; }
.unit { padding-left: 3px; font-size: 0.58em; vertical-align: top; }
.room-temperature { margin: 8px 0 22px; color: var(--muted); font-size: 0.9rem; letter-spacing: 0.08em; }
.room-temperature strong { color: var(--ink); }
.adjust-controls { display: flex; align-items: center; justify-content: center; gap: 18px; }
.adjust-button { width: 58px; height: 54px; border: 2px solid var(--line); border-radius: 12px; color: var(--ink); background: var(--panel); font-size: 1.8rem; cursor: pointer; transition: transform 100ms ease, background 120ms ease, border-color 120ms ease; }
.adjust-button:hover { border-color: var(--mint); background: #2a4842; }
.adjust-button:active { transform: translateY(2px); }
.adjust-button:disabled { opacity: 0.45; cursor: not-allowed; }
.step-note { color: var(--muted); font-size: 0.9rem; }
.mode-section { display: grid; gap: 9px; }
select { width: 100%; min-height: 52px; padding: 0 14px; border: 2px solid var(--line); border-radius: 10px; color: var(--ink); background: var(--panel); cursor: pointer; }
select:hover { border-color: var(--mint); }
.status { display: flex; align-items: center; gap: 10px; min-height: 54px; margin-top: 20px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 10px; color: var(--mint); background: var(--panel); font-weight: 650; }
.status[data-state="cooling"] { color: #9dd8e0; }
.status[data-state="idle"] { color: var(--muted); }
.status-indicator { width: 10px; height: 10px; flex: 0 0 auto; border-radius: 2px; background: currentColor; box-shadow: 0 0 12px currentColor; }
footer { display: flex; justify-content: space-between; margin-top: 18px; color: var(--muted); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08em; }
:focus-visible { outline: 3px solid var(--amber); outline-offset: 3px; }
@media (max-width: 390px) { .thermostat { padding: 22px 18px; } .adjust-controls { gap: 12px; } .adjust-button { width: 54px; } }

(() => {
  const MIN = 10;
  const MAX = 30;
  const STEP = 0.5;
  const ROOM = 21;
  let target = 21;

  const temperature = document.getElementById('target-temperature');
  const decrease = document.getElementById('decrease');
  const increase = document.getElementById('increase');
  const mode = document.getElementById('mode');
  const status = document.querySelector('.status');
  const statusText = document.getElementById('status-text');

  function update() {
    temperature.textContent = target.toFixed(1);
    decrease.disabled = target <= MIN;
    increase.disabled = target >= MAX;

    let state = 'idle';
    let message = 'Idle · room is at target';
    if (mode.value === 'heat' && target > ROOM) {
      state = 'heating';
      message = 'Heating · room is below target';
    } else if (mode.value === 'cool' && target < ROOM) {
      state = 'cooling';
      message = 'Cooling · room is above target';
    }
    status.dataset.state = state;
    statusText.textContent = message;
  }

  decrease.addEventListener('click', () => { target = Math.max(MIN, Math.round((target - STEP) * 10) / 10); update(); });
  increase.addEventListener('click', () => { target = Math.min(MAX, Math.round((target + STEP) * 10) / 10); update(); });
  mode.addEventListener('change', update);
  update();
})();
